entries[123211] = { ["name"] = "Schmerzmittel", ["text"] = "Sofort\nKlaxxiverstärkung\nVerliehen von Korven dem Ersten.\nErleidet ihr Schaden, der Euch töten würde, werdet Ihr stattdessen in Bern eingeschlossen, der den erlittenen Schaden verringert und Gesundheit und Mana während der Effektdauer wiederherstellt.\nDieser Effekt kann nur einmal alle 3 Minuten auftreten.\n\nEs kann immer nur jeweils eine Klaxxiverstärkung aktiv sein. Funktioniert nur in der Schreckensöde." }
