entries[123219] = { ["name"] = "Kampfeshymne", ["text"] = "Sofort\nKlaxxiverstärkung\nVerliehen von Skeer dem Blutsucher.\n\nLöst, wenn Ihr einen Gegner tötet, der Erfahrung gewährt den Effekt 'Kampfeshymne' aus, der 10 Sek. lang anhält.\n\nKampfeshymne\nAlle erfolgreichen Schadenszauber und -fähigkeiten stellen 1% Eurer Maximalgesundheit wieder her.\n\nEs kann immer nur jeweils eine Klaxxiverstärkung aktiv sein. Funktioniert nur in der Schreckensöde." }
