entries[123258] = { ["name"] = "Machtwort: Schild", ["text"] = "6.2% von Grundmana 40 Meter Reichweite\nSofort 6 sek. Abklingzeit\nNutzt die Seelenkraft eines befreundeten Ziels um es mit einem Schild zu umhüllen, der [(((Zaubermacht * 1.871) + 19428 ) * 1 )] Schaden absorbiert [ Glyphe 'Machtwort: Schild' : sowie das Ziel um 20% des absorbierten Wertes heilt ]. Hält 15 Sek. lang an. Solange der Schild hält, wird das Zauberwirken durch erlittenen Schaden nicht unterbrochen." }
entries[123259] = { ["name"] = "Gebet der Besserung", ["text"] = "3.5% von Grundmana 40 Meter Reichweite\nSofort\nBelegt das Ziel mit einem Zauber, der es um [(((( 3299 * 1.7948) + (Zaubermacht * 0.571)) * Prozentuale Gesundheit + 0 ) * (( 1 * 1 * 1 * 1 )))] heilt und dann zu einem Gruppen- oder Schlachtzugsmitglied innerhalb von 20 Metern überspringt. Springt bis zu 5 -mal. Dieser Zauber kann nur auf jeweils einem Ziel aktiv sein.\n(1s Abklingzeit)" }
