entries[123262] = { ["name"] = "Gebet der Besserung", ["text"] = "Unbegrenzte Reichweite\nSofort\nBelegt das Ziel mit einem Zauber, der es heilt, wenn es das nächste Mal Schaden erleidet. Wird die Heilung ausgelöst, springt 'Gebet der Besserung' zu einem Gruppen- oder Schlachtzugsmitglied innerhalb von 0 Metern über. Springt bis zu 0-mal und hält nach jedem Sprung 30 Sek. lang an. Dieser Zauber kann nur auf einem Ziel gleichzeitig aktiv sein." }
