entries[123402] = { ["name"] = "Schutz", ["text"] = "2 Chi\nSpontanzauber 30 sek. Abklingzeit\nBenötigt Ochsenstil\nIhr schützt Euch vor zukünftigen Angriffen und absorbiert 30 Sek. lang [((Angriffskraft * 1.971) + 14232 ) * 1 ] magischen Schaden.\n\nErhöht sämtliche Heilung, die Ihr auf Euch selbst wirkt, während 'Schutz' aktiv ist, um 30%." }
entries[123403] = { ["name"] = "Glyphe 'Fliegender Schlangentritt'", ["text"] = "Eure Fähigkeit 'Fliegender Schlangentritt' endet automatisch, wenn Ihr einen Gegner trefft, wodurch der Flächenschadenseffekt und die Verlangsamung ausgelöst werden." }
entries[123404] = { ["name"] = "Fliegender Schlangentritt" }
entries[123405] = { ["name"] = "Glyphe 'Wirbelnde Feuerblüte'", ["text"] = "Euer Zauber 'Wirbelnde Feuerblüte' benötigt ein gegnerisches Ziel anstatt sich vorwärts zu bewegen. Dafür werden Ziele nicht mehr bewegungsunfähig gemacht." }
entries[123406] = { ["name"] = "Wirbelnde Feuerblüte" }
entries[123407] = { ["name"] = "Wirbelnde Feuerblüte", ["text"] = "Unbegrenzte Reichweite\nSofort\nFügt dem ersten Ziel innerhalb von 50 Metern vor Euch [2.1 * ( 1 * 1 * ( 0.898882 * (Haupthand-Min-DPS * 1 + 1 * (Haupthand-Min-DPS / 2) ) + (Angriffskraft / 14) - 1))] bis [2.1 * ( 1 * 1 * ( 0.898882 * (Haupthand-Max-DPS * 1 + 1 * (Haupthand-Max-DPS / 2) ) + (Angriffskraft / 14) + 1))] Feuerschaden zu.\n\nWenn 'Wirbelnde Feuerblüte' weiter als 10 Meter fliegt, wird der Schaden um 50% erhöht und Ihr macht das Ziel 2 Sek. lang bewegungsunfähig." }
entries[123408] = { ["name"] = "Wirbelnde Feuerblüte", ["text"] = "1 Chi 50 Meter Reichweite\nSpontanzauber\nFügt dem Ziel 766 Feuerschaden zu.\n\nWenn 'Wirbelnde Feuerblüte' weiter als 10 Meter fliegt, wird der Schaden um 50% erhöht." }
