entries[124040] = { ["name"] = "Chitorpedo", ["text"] = "Unbegrenzte Reichweite\nSofort\nSchießt eine kurze Strecke vorwärts, fügt allen Gegnern entlang des Weges 2069 Naturschaden zu und heilt alle Verbündete darauf um [ 8408 + (Angriffskraft * .385)] Gesundheit.\n\n'Chitorpedo' ersetzt 'Rollen' und besitzt eine höhere Reichweite." }
entries[124041] = { ["name"] = "Gabe der Schlange", ["text"] = "Unbegrenzte Reichweite\nSofort\nBei Euren Heilungen besteht eine Chance von 10%, für 30 Sek. eine heilende Sphäre in der Nähe eines verletzten Verbündeten zu beschwören. Verbündete, die durch die Sphäre hindurchlaufen, werden um [((Angriffskraft * 0.3517) + 9986 )] geheilt.\n\nWenn die Dauer der heilenden Sphäre abläuft, bevor sie genutzt wurde, wird ein Verbündeter innerhalb von 6 Metern um die Sphäre um 50% ihres Effekts geheilt." }
